/* Intermediate 2 · ShopKaro DNS decisions, cache budgets and serving-state repair. */
(function () {
  const N=AG.aws.n, HC='00000000-0000-4000-8000-000000000001';
  const ALB='shop-alb.sim.ap-south-1.elb.amazonaws.com', ALB_ZONE='ZP97RAFLXTNZK';
  const R=(name,extra,ip,ttl=60)=>({Name:name+'.shopkaro.in.',Type:'A',TTL:ttl,ResourceRecords:[{Value:ip}],...extra});
  const weighted=()=>[R('checkout',{SetIdentifier:'v1',Weight:90},'203.0.113.11'),R('checkout',{SetIdentifier:'v2',Weight:10},'203.0.113.12')];
  const failover=()=>[R('status',{SetIdentifier:'primary',Failover:'PRIMARY',HealthCheckId:HC},'203.0.113.10'),R('status',{SetIdentifier:'maintenance',Failover:'SECONDARY'},'203.0.113.20')];
  const apex=()=>({Name:'shopkaro.in.',Type:'A',AliasTarget:{DNSName:ALB,HostedZoneId:ALB_ZONE,EvaluateTargetHealth:true}});
  const config=()=>({Type:'HTTP',IPAddress:'203.0.113.10',Port:80,ResourcePath:'/ready',RequestInterval:30,FailureThreshold:3});
  const batch=records=>({Changes:records.map(r=>({Action:'UPSERT',ResourceRecordSet:r}))});
  const file=value=>({content:JSON.stringify(value,null,2)});
  function seed(){return {region:'ap-south-1',elbs:[{id:'alb-shop',name:'shop-alb',type:'application',scheme:'internet-facing',dns:ALB,canonicalHostedZoneId:ALB_ZONE}],hostedZones:[{id:'ZSHOP',name:'shopkaro.in.',callerReference:'shop-original',records:[{Name:'shopkaro.in.',Type:'NS',TTL:172800,ResourceRecords:[{Value:'ns-1.sim.invalid.'},{Value:'ns-2.sim.invalid.'}]},{Name:'shopkaro.in.',Type:'SOA',TTL:900,ResourceRecords:[{Value:'ns-1.sim.invalid. hostmaster.sim.invalid. 1 7200 900 1209600 86400'}]},...weighted().map(r=>({...r,Weight:50})),...failover().map(r=>{const x={...r,TTL:3600};delete x.HealthCheckId;return x;})]}],healthChecks:[],dnsChanges:[],dnsAliases:[{dnsName:ALB,hostedZoneId:ALB_ZONE,healthy:true,addresses:['203.0.113.100']}],dnsHealthFixtures:{'203.0.113.10':false,'203.0.113.20':true},buckets:[{name:'shop-assets',public:false,encryption:true,objects:[]}]};}
  const zone=s=>(s.account.hostedZones||[]).find(z=>z.id==='ZSHOP');
  function eq(a,b){if(a===b)return true;if(!a||!b||typeof a!=='object'||typeof b!=='object')return false;const ak=Object.keys(a).sort(),bk=Object.keys(b).sort();return ak.length===bk.length&&ak.every((k,i)=>k===bk[i]&&eq(a[k],b[k]));}
  function contains(actual,expected){return expected.every(e=>actual.some(r=>r.Name===e.Name&&r.Type===e.Type&&r.SetIdentifier===e.SetIdentifier&&r.TTL===e.TTL&&r.Weight===e.Weight&&r.Failover===e.Failover&&r.HealthCheckId===e.HealthCheckId&&eq(r.ResourceRecords,e.ResourceRecords)&&eq(r.AliasTarget,e.AliasTarget)));}
  const served=s=>{const z=zone(s);return z?z.servedRecords||z.records||[]:[];};
  function healthOK(s){const h=(s.account.healthChecks||[]).find(h=>h.id===HC),c=h&&h.config;return !!c&&Object.entries(config()).every(([k,v])=>c[k]===v)&&!c.Disabled&&!c.Inverted&&h.observedHealthy===false&&(s.account.healthChecks||[]).length===1;}
  function preserved(s){const z=zone(s),b=(s.account.buckets||[]).find(b=>b.name==='shop-assets');return !!z&&z.name==='shopkaro.in.'&&z.callerReference==='shop-original'&&!z.private&&(s.account.hostedZones||[]).length===1&&contains(served(s),seed().hostedZones[0].records.slice(0,2))&&!!b&&!b.public&&b.encryption&&(s.account.elbs||[]).some(l=>l.id==='alb-shop'&&l.dns===ALB&&l.canonicalHostedZoneId===ALB_ZONE)&&(s.account.dnsAliases||[]).some(a=>a.dnsName===ALB&&a.hostedZoneId===ALB_ZONE&&a.healthy);}
  const SOLUTION=['aws route53 create-health-check --caller-reference shop-primary-v1 --health-check-config file://primary-health.json','aws route53 change-resource-record-sets --hosted-zone-id ZSHOP --change-batch file://apex-alias.json','aws route53 change-resource-record-sets --hosted-zone-id ZSHOP --change-batch file://weighted-90-10.json','aws route53 change-resource-record-sets --hosted-zone-id ZSHOP --change-batch file://failover-health.json','aws route53 wait resource-record-sets-changed --id /change/C000000003'];
  function budget(k){const ttl=[30,60,120,300,900,3600,86400][k.ttl],detect=k.interval*k.threshold+10,switchSeconds=detect+ttl+20,queries=k.queries*60/ttl,cost=0.50+queries*0.40+0.75+(k.interval===10?2:0);return {ttl,detect,switchSeconds,queries,cost,ok:k.queries>=10&&switchSeconds<=180&&cost<=6};}
  function Q(q,correct,wrong,answer,explain,domain){const choices=wrong.slice();choices.splice(answer,0,correct);return {q,choices,answer,explain,domain};}
  AG.registerLevels('intermediate',[{
    id:'route53',icon:'📡',title:'Route 53: DNS ka jawaab, canary aur failover mein der',badge:'DNS Daanish',
    hook:{when:'ShopKaro · public launch · course ki kahani (fictional)',title:'"Domain kharid liya. Apex CNAME reject kyun hua?"',text:'Ravi ne shopkaro.in kharida aur root naam par ALB hostname ka CNAME banaya. API ne request reject kar di. Priya checkout v2 ko thode se traffic (canary) par chalana chahti hai. Neha ko DB migration ke time maintenance page chahiye. DNS ka request baantna, browser ka traffic aur data ka ready hona: teeno alag controls hain. Guwahati ke ek cold resolver ka pehla lookup click karke dekho.'},
    objectives:['<b>Naam se IP</b>: delegation, public/private zone aur TTL ko trace karo','<b>Record ka chunav</b>: apex par Alias vs CNAME, aur ALB target ki details','<b>8 policies</b>: request ke context se policy chuno; users ka exact split mat maano','<b>Recovery</b>: health pakadna, resolver ka cache aur app/data ka ready hona alag rakho','<b>Hands-on</b>: asli ChangeBatch JSON, health check, propagation waiter aur jawaab dekho','<b>Lab ka saboot</b>: save hua data aur asli DNS/probe ka chalna alag pehchano'],
    steps:[
      {q:'Browser ko naam se IP kaise milta hai? TTL kya yaad rakhwata hai?',analogy:'Phone directory socho. Pehla office doosre office ka number deta hai. Aakhri phone number milne par caller use kuch time ke liye save kar leta hai. Save kiya number har call par directory se dobara nahi poocha jaata.',body:'<pre>Cold recursive resolver\n → root: .in nameservers?\n → .in: shopkaro.in nameservers?\n → Route 53 authoritative zone\n → Alias A answer → ALB IPs\n → browser connects to ALB</pre>',points:['Browser/OS apna sawaal recursive resolver ko bhejta hai. Root aur TLD aksar sirf agla pata (referral) dete hain; Route 53 aakhri pakka (authoritative) jawaab deta hai. Cache garam ho toh kuch steps chhoot jaate hain.','TTL seconds mein batata hai ki DNS jawaab kitni der cache mein rahe. TTL=3600 matlab naya cache purana jawaab lagbhag 1 ghanta rakh sakta hai. Ab TTL kam karne se pehle cache hue purane jawaab mit nahi jaate.','DNS TCP/UDP port 53 use karta hai; encrypted DNS bhi hota hai. DNS ka jawaab HTTP proxy nahi hai, aur khule connections ko shift nahi karta.'],asli:'Kaam: dry run mein "Agla" click karo. Resolver → root → .in → Route 53 ke labels dekho. ALB se connection DNS ke referrals ke baad hi shuru hota hai.'},
      {q:'Domain registration aur hosted zone ek cheez kyun nahi?',analogy:'Dukaan ka naam register karna aur public directory mein entry chhapna do alag kaam hain. Staff wali directory sirf office ke network mein dikhti hai.',body:'<div class="tbl-wrap"><table><tr><th>Cheez</th><th>Kaam</th><th>Debug ka saboot</th></tr><tr><td>Registrar / parent delegation</td><td>Domain ka maalik + pakke NS ka referral</td><td>Registrar ke NS public zone ke delegation set se match karein</td></tr><tr><td>Public hosted zone</td><td>Internet ke liye pakke records</td><td>NS, SOA, A/AAAA/Alias aur record policy</td></tr><tr><td>Private hosted zone</td><td>Judi hui VPCs/private resolver ke naam</td><td>VPC associations + DNS settings + Resolver ka raasta</td></tr></table></div>',points:['Hosted zone banana domain khareedna nahi hai. Registrar kahin aur bhi ho sakta hai. Parent ka NS delegation sahi Route 53 zone tak point karna chahiye.','NS batata hai ki pakke nameservers kaun hain. SOA zone ki authority/admin aur DNS timing ka data deta hai. Cleanup ke shortcut mein public zone ke default NS/SOA records delete mat karo.','Ek domain ki kai public zones ho sakti hain. Galat zone edit kiya toh API success degi, par public clients purani delegated zone ka jawaab lete rahenge.'],asli:'Kaam: lab setup ke baad list-resource-record-sets chalao. Nayi zone mein NS/SOA dikhenge. .test domain internet par delegation nahi banata.'},
      {q:'ALB ke liye Alias A kyun? CNAME aur aam A mein farak kya hai?',analogy:'Directory ki aam entry mein fixed phone number hota hai. CNAME kehta hai "doosre naam se poochho". Route 53 Alias chune hue AWS service se aakhri number khud nikaal kar deta hai.',body:'<div class="tbl-wrap"><table><tr><th>Choice</th><th>Value / apex</th><th>Kab use karein</th></tr><tr><td>A / AAAA</td><td>IPv4 / IPv6 address</td><td>Pakka, na badalne wala IP; A ki Value mein hostname galat</td></tr><tr><td>CNAME</td><td>DNS naam; zone apex par nahi</td><td>Subdomain → bahar ka hostname; us naam par koi aur record type nahi</td></tr><tr><td>Route 53 Alias A/AAAA</td><td>Supported target ka DNSName + HostedZoneId; apex par chalta hai</td><td>ALB, CloudFront, eligible AWS targets; target kya support karta hai check karo</td></tr><tr><td>MX / TXT</td><td>Mail ka raasta / text data</td><td>Email aur verification; app traffic routing policy ki jagah nahi</td></tr></table></div>',points:['Alias Route 53 ka apna feature hai, CNAME ka doosra naam nahi. Alias JSON mein AliasTarget hota hai; aam ResourceRecords/TTL mat likho. Alias ka TTL target ke niyam se aata hai; ALB Alias ALB ka 60-second TTL use karta hai.','ALB ka DNSName aur CanonicalHostedZoneId describe-load-balancers se padho. Target ka hosted-zone ID shopkaro.in zone ID se alag hai. ALB node ka IP code mein mat likho.','EvaluateTargetHealth supported target ki health le leta hai. ALB ke target group ki health maayne rakhti hai. CloudFront alias par EvaluateTargetHealth=true support nahi hai. Alias app ya data ki recovery ki guarantee nahi deta.','Alias AWS ke bahar ke kisi bhi hostname ko point nahi karta. Eligible ELB/CloudFront/S3 website alias queries free ho sakti hain; par saari DNS queries ya saare Alias targets free mat maano.'],asli:'Kaam: mission mein cat apex-alias.json likho. AliasTarget ke teen fields dekho; TTL/ResourceRecords nahi hone chahiye. S3 website endpoint sirf HTTP hai; HTTPS chahiye toh CloudFront wala design agle level mein aayega.'},
      {q:'8 routing policies mein faisla kis signal se hota hai?',analogy:'Directory operator kabhi fixed desk deta hai, kabhi capacity ki lottery, kabhi standby desk. Speed, jagah aur percent ki lottery teen alag sawaal hain.',body:'<div class="tbl-wrap"><table><tr><th>Policy</th><th>Kab use karein</th><th>Kab nahi / limit</th></tr><tr><td>Simple</td><td>Ek resource; ek set mein kai values ho sakti hain</td><td>Record par health check nahi; failover nahi</td></tr><tr><td>Weighted</td><td>90/10 DNS-query canary; weights 0–255</td><td>Bilkul 10% users/HTTP requests nahi; caches traffic jod dete hain</td></tr><tr><td>Latency</td><td>Configured AWS Regions mein sabse kam naapi latency</td><td>Sabse paas ki jagah ya data rakhne ke kanoon ka control nahi</td></tr><tr><td>Failover</td><td>Active-passive primary/secondary, health ke saath</td><td>Active-active request balancing nahi</td></tr><tr><td>Geolocation</td><td>User ka andaaza desh/continent/US state ke hisaab se content</td><td>Default record chahiye; sirf DNS data compliance laagu nahi kar sakta</td></tr><tr><td>Geoproximity</td><td>User aur resource ki jagah + bias se area chhota/bada</td><td>Latency+bias nahi; Jan 2024 se Traffic Flow ke bina bhi milta hai</td></tr><tr><td>Multivalue</td><td>8 tak healthy record jawaab, client chunta hai</td><td>Sessions, connection drain ya L7 load balancer ki guarantee nahi</td></tr><tr><td>IP-based</td><td>Jaane-pehchaane client/resolver CIDR → chuna hua endpoint</td><td>Desh ka andaaza nahi; source/ECS dikhta hai ya nahi check karo</td></tr></table></div>',points:['DNS ko aksar user ka nahi, recursive resolver ka IP dikhta hai. EDNS Client Subnet jagah ka andaaza behtar kar sakta hai. Jagah sirf andaaza hai; app ki permission aur data kahan rakha hai, yeh controls phir bhi chahiye.','Weight 0 wala record aam taur par tab tak bahar rehta hai jab tak positive weight wale healthy hain. Saare positive-weight records unhealthy hon, toh healthy zero-weight record ko bhi mauka milta hai. Saare weights 0 → sabko barabar chance; traffic band nahi hota.','Badi company ka example: ShopKaro ki 1 crore authoritative queries/mahina ko 90/10 weights do. Ek busy office resolver ka cache hua jawaab bahut saare shoppers share kar sakte hain. Har user ka experiment chahiye toh app ya session mein assignment karo. ShopKaro fictional hai; number sirf maana hua workload hai.'],asli:'Kaam: policy matching game solve karo. Interview ka agla sawaal: "sabse paas ka shehar" vs "sabse kam network latency" ka saboot kya hoga? Latency policy AWS ki latency measurements use karti hai, sirf doori nahi.'},
      {q:'Health check kaunsi failure pakadta hai? Default settings kya hain?',analogy:'Gate par guard "ready" ki ghanti bajata hai. Kai guards ki report jod kar faisla hota hai. Ek guard ki stopwatch poori duniya ke faisle ka exact SLA nahi hai.',body:'<p>Endpoint check HTTP/HTTPS/TCP dekhta hai. HTTP/HTTPS mein status 200–399 healthy maana jaata hai. Default: <b>har checker 30 second</b> par request bhejta hai, aur <b>lagatar 3 checks</b> fail hon tab unhealthy. Optional fast interval <b>10 second</b> ka extra charge lagta hai.</p>',points:['Duniya bhar ke kai checkers alag-alag probe karte hain. Yeh mat maano ki endpoint ko har 30 second mein kul ek hi request aayegi. Threshold×interval sirf budget ka rough andaaza hai, pakki global detection limit nahi.','Readiness path /ready ko asli dependency ki haalat dikhani chahiye. Hamesha 200 dene wala page DB write ki failure chhupa sakta hai. Check seedha naam wale endpoint ko dekhe; usi failover naam ko resolve karke ghoomta hua check mat banao.','Calculated health check chhote child checks ko jodta hai. Public checker private IP wale resource ko seedha probe nahi kar sakta. CloudWatch alarm wala check supported metric/alarm ki state dekh sakta hai; aksar custom metric chahiye.','Aam failover primary par HealthCheckId nahi hai, toh use healthy maana jaata hai. Alias mein EvaluateTargetHealth target ki health le sakta hai, isliye har Alias ke liye alag health check zaroori nahi. Disabled check healthy maana jaata hai; inverted check health ulat deta hai. AWS juda hua health check delete karne deta hai, par purane HealthCheckId ka aage ka routing status pakka nahi; association theek karo ya saaf karo.'],asli:'Kaam: triage mein primary record dekho. HealthCheckId nahi hai aur primary Alias nahi hai? Toh band endpoint ko DNS se hataane ka signal hi nahi hai.'},
      {q:'Primary band hua: saare clients turant backup par kyun nahi jaate?',analogy:'Directory mein badlav announce ho gaya. Par callers ke paas purane save kiye numbers hain, aur purani calls abhi chal rahi hain. Backup desk par customer ka khata bhi ready hona chahiye.',body:'<pre>Recovery ka budget (course ka andaaza):\nhealth ka faisla + bacha hua DNS TTL\n+ client/app retry aur cache ka time\n+ backend/data ready hone ka time (agar pehle se ready nahi)</pre>',points:['TTL 3600 se kam karne ke baad bhi pehle cache hua purana jawaab 1 ghante tak reh sakta hai. Migration se pehle TTL kam karo, purane cache ka time poora hone do, phir switch karo. App ke caches aur lambe connections DNS TTL se bhi zyada der tak purana raasta pakde reh sakte hain.','Route 53 get-change INSYNC ka matlab: Route 53 ke pakke servers update ho gaye. INSYNC se recursive cache saaf nahi hota, na pata chalta hai ki client jud gaya ya DB theek ho gaya.','Failover policy healthy primary chunti hai. Primary unhealthy aur secondary healthy ho, toh secondary. Dono unhealthy hon, toh primary ka jawaab aa sakta hai: yeh fail-open behaviour hai. DNS band ho jaayega, yeh mat maano.','DNS data copy nahi karta. DB replication ka lag RPO par asar daalta hai. Backup app ki capacity, credentials, session state aur likhne layak DB asli RTO par asar daalte hain. Read-only maintenance message confusion kam karta hai; checkout ka wapas chalna alag goal hai.'],example:'<div class="war-story"><b>Production mein aisa hota hai:</b> purane TTL wale resolvers fail hue primary ko hi use karte rehte hain; naye jawaab backup tak jaate hain. Jab traffic dono taraf bat raha ho, tab duplicate writes aur retries data ko galat kar sakte hain. App ki idempotency aur failover runbook test karo.</div>',asli:'Kaam: flowlab mein TTL 3600 se TTL 60 chuno. Switch ka andaaza kam hoga. Par model ke andaaze ko pakki maximum limit mat bolo.'},
      {q:'Office private zone ke naam kaise resolve karega? Kya public par apne aap wapas jaata hai?',analogy:'Staff wali directory office network se khulti hai. Door ki branch ko approved directory gateway chahiye. Staff wali entry na mile, toh woh apne aap public directory se nahi bhari jaati.',body:'<p>Private hosted zone judi hui VPCs ko naam deta hai. VPC ka DNS support/hostnames on rakho. On-premises se private zone resolve karne ke liye network ka raasta + <b>Resolver inbound endpoint</b> aur DNS forwarding set karo. VPC se on-premises naamon ke liye outbound endpoint + forwarding rule lagta hai; iska poora build Advanced networking level mein aayega.</p>',points:['Ek hi naam ki public aur private zones se split-horizon design banta hai. Judi VPC mein sabse specific private zone jeetti hai. Record na mile toh NXDOMAIN aa sakta hai; public par apne aap wapas nahi jaata.','Resolver endpoints ke ENIs, routing/security aur ghante/query ke charges hote hain. Aam private zone association ka kharcha endpoint ke ghante wale kharche se alag hai.','Galti jo sab karte hain: office ke DNS server mein private Route 53 zone ID paste karke sochna ki resolve ho jaayega. Zone ID DNS server ka IP nahi hai. Inbound endpoint ka IP + forwarding + network ka raasta chahiye.'],asli:'Yeh Route 53 mission public zone ka model hai. Private DNS forwarding, office VPN aur resolver ka asli cache lab10 mein nahi chalte.'},
      {q:'TTL aur policy chunte waqt bill kis cheez ki ginti karega?',analogy:'Directory counter har visitor nahi ginta; sirf counter par aaye lookup ginta hai. Cache se kiye gaye repeat calls counter tak aate hi nahi.',body:'<div class="tbl-wrap"><table><tr><th>Lagbhag public list price, US/commercial 2025–26</th><th>Unit</th></tr><tr><td>Pehli 25 hosted zones</td><td>$0.50/zone/mahina ≈ ₹44</td></tr><tr><td>Standard queries; pehle 1 billion/mahina</td><td>$0.40/million ≈ ₹35.20</td></tr><tr><td>Latency / geography queries</td><td>$0.60 / $0.70 har million ≈ ₹52.80 / ₹61.60</td></tr><tr><td>IP-based queries</td><td>$0.80/million ≈ ₹70.40</td></tr><tr><td>Basic non-AWS endpoint health check</td><td>$0.75/check/mahina ≈ ₹66</td></tr><tr><td>Fast 10s (optional, non-AWS)</td><td>+$2.00/check/mahina ≈ ₹176</td></tr></table></div>',points:['₹88 = $1 course ka conversion hai. Tax, domain registration, Resolver endpoints, target resources aur optional features alag. Query ka price tier/policy aur aaj ke daam check karo.','AWS endpoint ka basic check lagbhag $0.50/check/mahina hai; same/linked account ke 50 tak eligible AWS endpoint checks free ho sakte hain. Non-AWS example jaan-boojh kar $0.75/mahina aur bina free allowance ke liya gaya hai.','Flowlab maanta hai: TTL 60 second par 1 crore authoritative queries/mahina. Toy rule: queries ∝ 60/TTL. Asli query volume cache ke design, traffic aur records par depend karta hai; sirf TTL se production bill nahi nikalta.'],asli:'Kaam: TTL 60, interval 30, threshold 3, demand 1 crore/mahina set karo. Course ka budget: detection 100 second + TTL 60 + client 20 = 180 second; kharcha lagbhag $0.50+$4+$0.75 = $5.25/mahina (₹462). Asli der is toy andaaze se bandhi nahi hai.'},
    ],
    myth:[{myth:'CNAME aur Alias ek hi hain; apex par CNAME ALB hostname le lega.',sach:'Apex par CNAME galat hai. Supported ALB target ke liye Alias A/AAAA aur target zone ki details use karo. A ki Value mein IP hi hona chahiye.'},{myth:'Weight 10 matlab bilkul 10% users; weight 0 saara traffic band kar deta hai.',sach:'Weights pakke DNS jawaabon ka hissa tay karte hain. Caches aur users ke group alag hote hain. Saare weights 0 → barabar chance. Positive wale saare unhealthy hon toh zero-weight ko mauka mil sakta hai.'},{myth:'Primary record hai + secondary record hai = turant apne aap DR.',sach:'Health association ya inherited health, detection, purana TTL, app ka retry aur data/capacity ka ready hona: sab chahiye. INSYNC client ka cache saaf nahi karta.'},{myth:'Geoproximity = latency+bias, aur Traffic Flow zaroori hai.',sach:'Geoproximity doori + bias hai; Jan 2024 se seedhe records mein milta hai. Latency policy naapi hui performance par alag faisla hai.'}],
    playbook:{title:'Kab use karein / kab nahi: DNS routing ka faisla',use:['DNS level par active-passive endpoint chunna, cache aur recovery ka budget test karke','Weighted se dheere-dheere naya endpoint; asli HTTP/user experiment alag se naapo','Apex par supported AWS target, ya private/hybrid naam saaf delegation ke saath'],avoid:['Har request ka turant control, sticky groups, connection drain, ya pakki global switch deadline','Sirf DNS geolocation ko data residency ya security ka control maanna','Database replication ya backup recovery ki jagah DNS'],how:['Registrar delegation/zone + exact naam/type pehchano','Apex? Supported Alias. Bahar ka subdomain? CNAME. Pakka IP? A/AAAA','Percent? Weighted. Naapi speed? Latency. Standby? Failover. Jagah? Geolocation/geoproximity. Pehchane CIDR? IP-based','Health ka link, pending changes, purana TTL aur asli app/data ka ready hona dekho','Ek saath JSON apply karo; authoritative INSYNC ka wait karo; jawaab dekho aur jahan allowed ho wahan asli clients test karo'],redflags:['A ki Value mein ALB hostname; apex par CNAME','Aam primary bina HealthCheckId; disabled/inverted check failure chhupa deta hai','Jaldi wale planned cutover mein TTL 3600; "bilkul 10% users" ka vaada','Private zone mein record missing; public par wapas jaane ka galat bharosa'],rule:'Faisla kaise karein: ek resource → simple; canary → weighted; active-passive → failover; sabse tez region → latency; desh → geolocation; doori+bias → geoproximity; pehchane CIDR → IP-based; kai healthy IP jawaab → multivalue.'},
    exam:[{cue:'"zone apex points to ALB"',pick:'Alias A/AAAA to supported target',why:'Apex par CNAME allowed nahi; target ka HostedZoneId zone ID se alag hai.'},{cue:'"canary endpoint receives about 10% DNS answers"',pick:'Weighted90/10',why:'Users, requests ya shared resolver groups ke baare mein guarantee nahi.'},{cue:'"best measured regional performance"',pick:'Latency routing',why:'AWS ka latency data, sirf sabse kam doori nahi.'},{cue:'"country/continent-specific DNS answer"',pick:'Geolocation + default record',why:'Jagah sirf andaaza; app/data compliance ke controls phir bhi chahiye.'},{cue:'"resource location plus adjustable bias"',pick:'Geoproximity',why:'Jagah ke hisaab se area; Traffic Flow ke bina seedhe records support hote hain.'},{cue:'"active-passive DR"',pick:'Failover + health + cache/data runbook',why:'Aam primary bina check ke healthy rehta hai; Alias mein inherit hone ka niyam alag hai.'},{cue:'"return several healthy IP records"',pick:'Multivalue, up to 8',why:'Poore load balancer jaisa kaam nahi.'},{cue:'"known client CIDR ranges"',pick:'IP-based routing',why:'Set ki hui CIDR collection; desh ka andaaza nahi.'},{cue:'"on-prem resolves private hosted zone"',pick:'Resolver inbound endpoint + forwarding/path',why:'Private endpoint ke checks public probe ki jagah supported CloudWatch alarm ki state use kar sakte hain.'}],
    stages:[
      {type:'dryrun',title:'🔍 Guwahati ke resolver se canary aur maintenance tak',goal:'"Agla" click karo: cold referral chain, Alias ka jawaab, weighted chunav aur purana cache. Do faislon ka jawaab do.',nodes:[N('user',110,70,{label:'Guwahati'}),N('r53#resolver',370,70,{label:'Recursive resolver'}),N('internet#root',650,70,{label:'Root → .in'}),N('r53',370,245,{label:'Route 53 zone'}),N('alb',780,245,{label:'ALB / apex Alias'}),N('ec2#v1',120,420,{label:'checkout v1 / 90'}),N('ec2#v2',430,420,{label:'checkout v2 / 10'}),N('cf',790,420,{label:'Maintenance CDN'})],edges:[{from:'user',to:'r53#resolver'},{from:'r53#resolver',to:'internet#root'},{from:'r53#resolver',to:'r53'},{from:'r53',to:'alb'},{from:'r53',to:'ec2#v1'},{from:'r53',to:'ec2#v2'},{from:'r53',to:'cf'}],panels:[{id:'answer',title:'Authoritative answer'},{id:'cache',title:'Resolver / application boundary'}],steps:[
        {clock:'cold lookup',say:'Browser recursive resolver se shopkaro.in poochta hai. Cold resolver root aur .in se referrals leta hai, phir delegated Route 53 nameservers se poochta hai. Referrals IP request ko app tak proxy nahi karte.',flows:[{from:'user',to:'r53#resolver',tone:'ok'},{from:'r53#resolver',to:'internet#root',label:'NS referrals',tone:'ok'},{from:'r53#resolver',to:'r53',label:'A query',tone:'ok'}],panels:{answer:['Parent delegation sahi public zone batata hai'],cache:['Garam cache root/TLD lookup chhod sakta hai']}},
        {clock:'apex Alias',say:'Zone apex ka Alias A ALB ke aaj ke IPs ka jawaab deta hai. Aam A ki Value mein ALB hostname galat hai. IP milne par browser ALB se connection shuru karta hai.',flows:[{from:'r53',to:'alb',label:'Alias A answer',tone:'ok'}],panels:{answer:['AliasTarget: DNSName + target ka HostedZoneId','ALB ke TTL niyam; Alias ka apna TTL nahi'],cache:['DNS checkout requests ko proxy nahi karta']},ask:{q:'Ravi shopkaro.in apex ko ALB hostname par point karna chahta hai. Kaunsa record sahi hai?',choices:['Alias A, ALB ke DNSName aur canonical target zone ID ke saath','Apex par CNAME, chhote TTL ke saath aur koi aur setting nahi','Aam A record, jiski ResourceRecords Value mein ALB DNSName ho','NS record jisme nameservers ki jagah ALB ka DNSName likha ho'],answer:0,explain:'Supported Alias apex par chalta hai. Apex par CNAME zaroori NS/SOA se takraata hai. A ko IP chahiye. NS DNS servers ko delegate karta hai, ALB ko nahi.'}},
        {clock:'90 / 10',say:'checkout.shopkaro.in ke weighted records v1=90/v2=10 hain. Pakka chunav lagbhag 90/10 DNS queries baant-ta hai. Par ek resolver ka cache hua jawaab bahut saare HTTP shoppers share kar sakte hain.',flows:[{from:'r53',to:'ec2#v1',label:'weight90',tone:'ok'},{from:'r53',to:'ec2#v2',label:'weight10',tone:'slow'}],panels:{answer:['Relative weights; shoppers ka koi fixed hissa nahi'],cache:['Session level ke experiment ke liye app mein assignment chahiye']}},
        {clock:'primary unhealthy',say:'Readiness checks batate hain ki primary band hai. Failover group naye pakke lookups ke liye secondary maintenance jawaab chunta hai. Maintenance ka CloudFront/S3 design agle CDN level mein banega; abhi CLI fixture documentation IPs use karta hai.',flows:[{from:'r53',to:'cf',label:'fresh answer',tone:'ok'}],panels:{answer:['Primary check ya inherited health ka association chahiye'],cache:['Purane primary connections shift nahi hote']}},
        {clock:'old cache',say:'Resolver ne failure se thik pehle TTL 3600 ke saath primary ka jawaab save kiya. Failure ke baad TTL kam karne se purana cache saaf nahi hota. App ka cache ya connection ki umar aur der jod sakte hain.',panels:{cache:['Purana bacha TTL lagbhag 1 ghanta ho sakta hai','Clients ke switch hone ki koi pakki limit nahi']},ask:{q:'TTL 3600 tha. Naya secondary jawaab aane ke baad saare clients kab switch karenge?',choices:['Pakki guarantee nahi; purana cache primary ko ~1 ghanta rakh sakta hai, app aur der jodta hai','Bilkul 30 second, kyunki health interval saare recursive DNS caches saaf kar deta hai','INSYNC ke turant baad, kyunki Route 53 browser ke connection pools saaf kar deta hai','Har minute bilkul 10%, kyunki weighted canary failover ke cache expiry ko control karta hai'],answer:0,explain:'TTL DNS cache ki umar batata hai. Check interval aur INSYNC client caches saaf nahi karte. Weighted hisse ka cache expiry se koi lena-dena nahi. App ka behaviour aur der jod sakta hai.'}},
        {clock:'runbook',say:'Planned migration: TTL pehle se kam karo, purane cache ka time poora hone do, standby app/data ka ready hona check karo, phir cutover karke clients dekho. DNS recovery ka budget aur data RPO alag-alag naapo.',panels:{answer:['Waiter: authoritative config sync ho gaya'],cache:['App retry/idempotency aur replica lag phir bhi maayne rakhte hain']}},
      ],lesson:'DNS lookup ke waqt jawaab chunta hai. Alias target, relative weights, health aur purane caches milkar traffic tay karte hain. App ke turant global failover ka koi vaada nahi.'},
      {type:'flowlab',title:'🎛️ Cache budget: recovery aur query ka bill',goal:'Demand kam se kam 1 crore/mahina (TTL 60 par), client switch ≤180 second, aur DNS/check ka kharcha lagbhag ≤$6/mahina. Demand kam karke jeetna nahi chalega.',scenario:'Yeh course ka andaaza hai, AWS ki worst-case guarantee nahi: detection = interval × threshold + 10 second jodne ka time; switch = detection + TTL + 20 second client ka time. Asli checkers, caches aur connections zyada time le sakte hain. Query ka toy rule = reference demand × 60 / TTL; koi universal niyam nahi. Ek public zone + non-AWS HTTP check, standard queries, ₹88 = $1; AWS targets/data/Resolver/tax alag.',knobs:[{id:'ttl',label:'TTL choice',min:0,max:6,step:1,value:5,labels:{0:'30 seconds',1:'60 seconds',2:'120 seconds',3:'300 seconds',4:'900 seconds',5:'3600 seconds',6:'86400 seconds'}},{id:'interval',label:'Per-checker interval',min:10,max:30,step:20,value:30,unit:' seconds'},{id:'threshold',label:'Consecutive failures',min:1,max:10,step:1,value:3,unit:' checks'},{id:'queries',label:'Query demand',min:1,max:10,step:1,value:10,unit:' M/month'}],model:k=>{const b=budget(k);return {readouts:[{label:'Modeled detection budget',value:b.detect+' seconds',tone:'info'},{label:'Modeled client switch',value:b.switchSeconds+' seconds',tone:b.switchSeconds<=180?'ok':'bad'},{label:'Estimated authoritative queries',value:b.queries.toFixed(3)+' million/month',tone:'info'},{label:'Lagbhag DNS/check kharcha',value:'$'+b.cost.toFixed(2)+'/month · ₹'+Math.round(b.cost*88),tone:b.cost<=6?'ok':'bad'},{label:'Demand preserved?',value:k.queries>=10?'1 crore/mahina reference bana raha':'Demand fixed workload se kam',tone:k.queries>=10?'ok':'bad'}],verdict:{ok:b.ok,text:b.ok?'Course ka budget pass. Asli migration se pehle resolver/client ka asli behaviour aur targets ka poora kharcha naapo.':'Example: TTL 60 second, interval 30 second, threshold 3, demand 1 crore/mahina → 180 second aur lagbhag $5.25/mahina.'}};},check:k=>budget(k).ok,lesson:'TTL 60 / interval 30 / threshold 3 / demand 1 crore → detection 100 second + TTL 60 + 20 = 180 second; lagbhag $5.25/mahina. Fast 10 second non-AWS check ki fees lagbhag $2/mahina badhata hai. Dono hisaab end-user ki asli recovery ki guarantee nahi dete.'},
      {type:'match',title:'🧩 Requirement → routing signal',instructions:'Har use case ko uski alag policy se jodo. DNS policy app ki guarantees ki jagah nahi leti.',pairs:[{left:'Ek ALB, policy health check ki zaroorat nahi',right:'Simple',explain:'Ek logical endpoint; Alias supported target ki health le sakta hai.'},{left:'Naye endpoint ko lagbhag 10% DNS jawaab',right:'Weighted',explain:'Relative DNS weights; user/request ke experiment ke liye alag control chahiye.'},{left:'Sabse kam naapi gayi regional network latency',right:'Latency',explain:'AWS ki measurement, sirf doori nahi.'},{left:'Primary unhealthy → standby',right:'Failover',explain:'Health association aur client/cache/data ka budget chahiye.'},{left:'Desh/continent ke hisaab se content',right:'Geolocation',explain:'Source ki jagah ka andaaza; default record jodo; akela kanooni control nahi.'},{left:'Bias se jagah ka area bada karo',right:'Geoproximity',explain:'User/resource ki jagah aur bias; latency+bias nahi.'},{left:'8 tak healthy record jawaab',right:'Multivalue',explain:'DNS level par phailana; poora L7 load balancer nahi.'},{left:'Pehchane customer CIDR → endpoint ka mapping',right:'IP-based',explain:'CIDR collection aur source/ECS dikhna; desh ka andaaza nahi.'}]},
      {type:'bins',title:'🗂️ Alias / CNAME / dono / koi nahi',instructions:'Alias aur CNAME kya kar sakte hain, compare karo; asli target ka support phir bhi check karo.',bins:[{id:'alias',label:'Alias only'},{id:'cname',label:'CNAME only'},{id:'both',label:'Dono possible'},{id:'neither',label:'Koi nahi'}],items:[{text:'Zone apex shopkaro.in → supported ALB DNS target',bin:'alias',explain:'Apex par Alias sahi; apex par CNAME allowed nahi.'},{text:'news.shopkaro.in → kisi bahar ki company ka hostname, aur koi record nahi',bin:'cname',explain:'CNAME bahar ke naam le sakta hai; Alias kisi bhi bahar ke hostname ko nahi leta.'},{text:'app.shopkaro.in → supported ALB hostname, aur koi record nahi',bin:'both',explain:'Subdomain par CNAME chal sakta hai; Alias A aksar ek extra DNS lookup aur eligible query charge bachata hai.'},{text:'Eligible ALB target ka jawaab, bina Route53 Alias query charge ke',bin:'alias',explain:'Eligible Alias queries free; CNAME ki query chain par charge lag sakta hai.'},{text:'Apex → supported same-name S3 website endpoint',bin:'alias',explain:'Alias target supported hai; S3 website sirf HTTP hai aur bucket ke naam ke niyam maayne rakhte hain.'},{text:'Koi bhi IPv4 address AliasTarget DNSName ya CNAME mein daal do',bin:'neither',explain:'Pakka IPv4 aam A ResourceRecords mein jaata hai, hostname/target fields mein nahi.'}]},
      {type:'triage',title:'🩺 Primary band hai, phir bhi DNS primary bata raha hai',symptom:'status.shopkaro.in ka failover pair Alias nahi hai. Primary HTTP fixture kai check windows se band hai; phir bhi naya pakka jawaab 203.0.113.10 hi aa raha hai. Kaunsa signal missing hai, dhoondo.',commands:[{cmd:'aws route53 list-resource-record-sets --hosted-zone-id ZSHOP',out:'{"ResourceRecordSets":[{"Name":"status.shopkaro.in.","Type":"A","SetIdentifier":"primary","Failover":"PRIMARY","TTL":60,"ResourceRecords":[{"Value":"203.0.113.10"}]},{"Name":"status.shopkaro.in.","Type":"A","SetIdentifier":"maintenance","Failover":"SECONDARY","TTL":60,"ResourceRecords":[{"Value":"203.0.113.20"}]}]}',clue:true,note:'Aam primary par na HealthCheckId hai, na AliasTarget se health milti hai. Route53 primary ko healthy maanta hai.'},{cmd:'aws route53 list-health-checks',out:'{"HealthChecks":[]}',clue:true,note:'Koi endpoint check nahi hai; sirf check banana kaafi nahi, record se jodna bhi padega.'},{cmd:'aws route53 test-dns-answer --hosted-zone-id ZSHOP --record-name status.shopkaro.in --record-type A',out:'{"RecordData":["203.0.113.10"],"ResponseCode":"NOERROR"}',clue:false,note:'Naya pakka (authoritative) jawaab; yeh purane recursive cache ka saboot nahi.'},{cmd:'aws route53 get-change --id /change/C000000001',out:'{"ChangeInfo":{"Id":"/change/C000000001","Status":"INSYNC"}}',clue:false,note:'Publish hue config mein health association nahi; galat config sync ho kar bhi galat hi rehta hai.'}],questions:[Q('Naye primary jawaab ki sabse mazboot wajah kya hai?','Non-alias primary par health association nahi, isliye DNS primary ko healthy maanta hai',['Failover se pehle secondary ka IPv4 address primary ke address jaisa hona chahiye','TTL 60 itni jaldi khatam hota hai ki koi pakka server secondary chun hi nahi paata','INSYNC tab tak primary jawaab deta hai jab tak operator public hosted zone delete na kare'],0,'HealthCheckId na hone se aam primary healthy rehta hai. Secondary alag hona chahiye. TTL cache par asar daalta hai, health nahi jodta. INSYNC config publish karta hai, aur zone delete karna DNS ko hi khatam kar deta hai.','resilient'),Q('Active-passive routing ko bachate hue repair kya hai?','Readiness check banao, primary ke HealthCheckId se jodo, phir pakka jawaab check karo',['Health jode bina primary ka TTL kam karo, kyunki cache expiry khud health bana deta hai','Weighted v2 ko 100 kar do aur maan lo ki doosre naam se failover pair theek ho jaayega','NS aur SOA records hata do, taaki parent delegation apne aap standby IPv4 chun le'],1,'Check + association se failure ka signal milta hai. Sirf TTL se health nahi banti. Checkout ke weights doosre naam par lagte hain. NS/SOA hataana authority tod deta hai, failover nahi banata.','resilient')]},
      (function(){const tasks=[{text:'Apex ka chalu Alias A purane ALB target par, inherited health ke saath',check:s=>contains(served(s),[apex()])},{text:'Chalu checkout records v1=90/v2=10, TTL 60, purane do endpoints',check:s=>contains(served(s),weighted())},{text:'Enabled, non-inverted /ready HTTP primary check: sahi endpoint, interval 30, threshold 3',check:healthOK},{text:'Chalu status primary check se juda; secondary maintenance; TTL 60; unhealthy primary par secondary resolve',check:s=>contains(served(s),failover())&&!!zone(s)&&eq(AG.dnsAnswer(s.account,zone(s),'status.shopkaro.in','A'),['203.0.113.20'])},{text:'Authoritative changes INSYNC; sirf 7 planned records; purani zone, NS/SOA, ALB aur private assets bache rahe',check:s=>preserved(s)&&served(s).length===7&&(s.account.dnsChanges||[]).length>0&&(s.account.dnsChanges||[]).every(c=>c.Status==='INSYNC')}];return {type:'terminal',title:'🖥️ Mission: sahi records, health aur propagation',instructions:'ls se chaar JSON files dekho; cat filename se andar padho. Pehle health check ka ID 00000000-0000-4000-8000-000000000001 aayega; teen changes C000000001/2/3. Baad wala waiter usi zone ke pichhle changes bhi publish karta hai. Paanch commands chahiye; koi nakli apply command nahi.',goal:'Pehle se bani ZSHOP/shopkaro.in ko bachao. Apex Alias A → purana ALB; checkout v1/v2 weights 90/10, TTL 60; status failover: primary par /ready HTTP check + maintenance secondary, TTL 60. Fixture primary 203.0.113.10 band hai; fixture secondary 203.0.113.20 healthy. Saare edits authoritative INSYNC hone chahiye. JSON files ready hain; target ki details lab fixture hain. Asli probes, recursive cache ya propagation ka time simulate nahi hota.',account:seed(),files:{'primary-health.json':file(config()),'apex-alias.json':file(batch([apex()])),'weighted-90-10.json':file(batch(weighted())),'failover-health.json':file(batch(failover()))},tasks,success:AG.allOf(tasks),solution:SOLUTION.slice(),hints:[SOLUTION[0]+' — ishara: pehle primary ka readiness signal banao; cat primary-health.json padho',SOLUTION[1]+' — apex AliasTarget use karta hai, A Value mein ALB hostname nahi',SOLUTION[2]+' — same naam/type ka pair, alag SetIdentifier aur dono ka TTL 60',SOLUTION[3]+' — primary HealthCheckId bane hue check se jude; secondary bina check ke fixture mein healthy maana jaata hai',SOLUTION[4]+' — aakhri C000000003 waiter zone ke pichhle changes bhi publish karta hai; is model mein sirf get-change pending state dikhata hai'],successText:'Authoritative chalu snapshot theek ho gaya. Jawaab check: status.shopkaro.in → 203.0.113.20. Aakhri waiter se pehle read-only test-dns-answer purana snapshot dikhata hai; mission poora hone par terminal lock ho jaata hai. DNS jawaab ka model fixture ki health use karta hai; asli DNS caches, ALB ka ready hona aur client/data recovery alag test hain.'};})(),
      {type:'docker',title:'🐳 Lab10: asli Route53 API ka data',project:'10-route53-routing',goal:'README ke ex1–ex5: lab ka ALB/zone banao → Alias/weighted/failover JSON → health association hatao aur wapas lagao → emulator ki limits dekho → sirf apne resources ka cleanup.',why:'Asli CLI JSON aur data save karne ki practice milegi. Moto asli DNS/HTTP probe nahi karta; test-dns-answer abhi 404 deta hai, aur bana-banaya health jawaab endpoint ka saboot nahi.',steps:[{text:'README Setup ke exports chalao, phir lab ka apna VPC/ALB/public zone banao.',cmd:'cd aws-gurukul/docker-labs\n./start-moto.sh\nsource env.sh\ncd 10-route53-routing\n# README Setup isolation exports run karo.\nbash setup.sh\nsource .lab/resources.sh',expect:'["NS","SOA"] and ALB canonical zone Z2P70J7EXAMPLE in current Moto.'},{text:'Asli CLI se health check aur JSON ChangeBatch save karo, phir config dekho.',cmd:'bash exercises.sh\nsource .lab/resources.sh',expect:'"INSYNC"; v1 Weight90 / v2 Weight 10; PRIMARY has HealthCheckId; SECONDARY has null Check.'},{text:'Primary ka health association hatao, missing Check dekho, phir wapas lagao.',cmd:'aws route53 change-resource-record-sets --hosted-zone-id "$ZONE" --change-batch file://.lab/missing-health.json\naws route53 change-resource-record-sets --hosted-zone-id "$ZONE" --change-batch file://.lab/repair.json',expect:'Both edits return ChangeInfo Status=INSYNC in current Moto; README query shows null then restored ID.'},{text:'Optional test-dns-answer abhi emulator mein 404 dikhata hai; cleanup sirf lab ke resources hataata hai.',cmd:'aws route53 test-dns-answer --hosted-zone-id "$ZONE" --record-name status.shopkaro-lab10.test --record-type A\nbash cleanup.sh',expect:'An error occurred (404) when calling the TestDNSAnswer operation: Not Found. Cleanup: four empty lists.'}],observe:Q('Moto documentation IP ke liye HTTP 200 kehta hai aur test-dns-answer 404 deta hai. Asal mein kya pass hua?','Health/record ka data save hua; asli probe aur DNS jawaab abhi check nahi hue',['Chalu HTTP readiness test aur poora public DNS delegation data se naap liya gaya','180 second ke andar app failover pakka hua aur users ka bilkul 10% hissa bana','Asli AWS service har test-dns-answer call reject karti hai, kyunki yeh operation galat hai'],2,'Data save ho gaya. Nakli endpoint ka bana-banaya HTTP 200 asli probe nahi. DNS, latency ya canary ka koi measurement nahi. TestDNSAnswer asli AWS API hai, bas abhi Moto ka endpoint fail hua.','resilient')},
      {type:'quiz',title:'📝 Bonus: asli shartein, DNS ke faisle',questions:[
        Q('shopkaro.in apex ko ALB par point karna hai, node IPs fix kiye bina. Sabse achha record?','Alias A, ALB ke DNSName aur ALB ke canonical hosted-zone ID ke saath',['shopkaro.in par CNAME, ALB hostname aur custom TTL 60 ke saath','Aam A record, jiski ResourceRecords Value ALB ka hostname hai','NS record, jiski nameserver value ALB endpoint ka DNS naam hai'],0,'Alias apex par eligible targets support karta hai. Apex CNAME zaroori zone records se takraata hai. Aam A ko IPv4 chahiye. NS DNS ki authority delegate karta hai, HTTP traffic nahi.','high-performing'),
        Q('90/10 weighted DNS canary mein 35% HTTP requests v2 par ja rahi hain. Yeh kaise ho sakta hai?','Resolver cache aur clients ka connection reuse DNS ka hissa HTTP se alag kar dete hain',['Weight 10 matlab har second 10 clients, chahe resolver queries ya TTL kuch bhi ho','Route53 har fail hui checkout request ko v2 ki safal request mein badal deta hai','Aam weighted record apne aap users ka ek pakka 10% group bana kar rakhta hai'],1,'Weights sirf pakke jawaabon par asar daalte hain; shared caches aur connections aage ki ginti badal dete hain. Weights relative hain, requests/second nahi. DNS checkout ka result nahi dekhta, na users ke pakke group banata hai.','high-performing'),
        Q('Jo region sabse paas hai, woh network measurement mein dheema hai. Speed ke liye kaunsi policy?','Configured AWS Regions mein latency routing, AWS ke measurement data ke hisaab se',['Zero bias ke saath geoproximity routing, jo seedha HTTP response ki speed naapti hai','Desh ke hisaab se geolocation routing, jo sabse kam naapi latency chunti hai','Do IPs ke saath simple routing, jo har client connection ko RTT se rank karti hai'],2,'Latency policy AWS ka latency data use karti hai. Geoproximity doori+bias dekhti hai; geolocation jagah map karti hai; simple multi-value client ka RTT naap kar rank nahi karta.','high-performing'),
        Q('Primary fail hua; failover check unhealthy hai; phir bhi kuch clients purana IP use kar rahe hain. Kyun?','Resolver ka purana cache aur chalu connections authoritative update ke baad bhi chalte rehte hain',['INSYNC har recursive resolver ko zone dobara banne tak primary pakde rehne ko kehta hai','Cache wale clients failover use karein, iske liye secondary ka IP primary jaisa hona chahiye','Failure threshold har database row ko apne aap standby storage mein copy kar deta hai'],3,'Cache TTL aur connection/app ka behaviour naya jawaab apnane mein der kar sakte hain. INSYNC na primary ko pakadta hai na cache saaf karta hai. Secondary alag hota hai. Health threshold data copy nahi karta.','resilient'),
        Q('User/resource ki jagah ke saath area badalne wala bias chahiye, aur TrafficFlow zaroori na ho. Kya chunoge?','Geoproximity records; TrafficFlow ke bina seedhi policy support hai',['Latency records; latency policy mein geographic bias ek zaroori parameter hai','Weighted records; percent values jagah ke area ka exact radius batate hain','Geolocation records; desh ki mapping resource ki doori ka bias khud set karti hai'],0,'Geoproximity doori+bias support karti hai, aur Jan 2024 se seedhe records mein. Latency mein jagah ka bias nahi hota; weights jagah ka radius nahi; geolocation region map karti hai, doori ka area nahi.','high-performing'),
        Q('Public health checkers private DB ki readiness tak nahi pahunch sakte. Signal kya ho sakta hai?','Supported CloudWatch alarm wala health check, DB readiness ki kaam ki metric ke saath',['HTTP endpoint health check jo internet se seedha RFC1918 DB address ko probe kare','Zero child threshold wala calculated check, jo har DB query ka safal hona prove kare','Private hosted-zone Alias jo apne aap authenticated SQL transactions chala deta hai'],1,'Alarm wali health supported metrics/alarms se private resource ki health dikha sakti hai. Public checks private IPs tak nahi pahunchte. Zero threshold wala calculated check hamesha healthy rehta hai. Alias SQL nahi chalata.','resilient'),
        Q('Saare weighted records ka Weight 0 hai. Baaki sab same ho toh kya hoga?','Records barabar chance ke saath eligible rehte hain; sab zero matlab traffic band nahi',['Har pakki query ko NXDOMAIN milega jab tak koi weight positive na ho','Sirf alphabet mein pehla SetIdentifier saara traffic lene ke liye bachta hai','DNS ek TTL ke baad har zero-weight record apne aap delete kar deta hai'],2,'Saare zero weights ko barabar chance milta hai. Zero se record delete nahi hota, na NXDOMAIN aata hai; "pehla identifier hi jeetega" jaisa koi AWS niyam nahi. Positive-healthy vs zero fallback ek alag case hai.','resilient'),
        Q('Office DNS ko judi VPC ki private zone ke naam chahiye. Kaunsi direction chahiye?','Resolver inbound endpoint, office mein forwarding aur allowed network ka raasta',['Sirf Resolver outbound endpoint, bina forwarding ya office DNS se route ke','Private hosted-zone ID ko public NS delegation, jaise ID koi IP ho','Har private IP ka public CNAME, bina private DNS raaste ya permissions ke'],3,'Inbound on-premises se VPC mein aane wali queries leta hai. Outbound VPC se bahar ki direction ke liye hai. Zone ID server ka IP nahi. Public CNAME allowed private resolver ka raasta nahi.','secure'),
      ]},
    ],
    interview:{title:'🎤 DNS incident review',instructions:'Jawaab ka scope, cache ka behaviour aur health ka saboot samjhao. Aakhri kaam pehle se bane data ko theek karta hai.',questions:[
      Q('Non-alias primary failover record par HealthCheckId nahi hai. DNS kya maanta hai?','Primary healthy maana jaata hai; apne aap failure chunne ke liye readiness signal jodo',['Primary unhealthy maana jaata hai, kyunki aam record mein AliasTarget field nahi hai','Har lookup se pehle dono records apne DNS naam se apne aap probe hote hain','Check na hone se poori authoritative zone NS jawaab dena band kar deti hai'],0,'Health check na juda ho, toh aam taur par healthy maana jaata hai. Aam record ko Alias hona zaroori nahi. Har query par endpoint ka probe apne aap nahi hota. NS authority alag rehti hai.','resilient'),
      Q('Compliance team EU data residency maangti hai. Sirf DNS geolocation kya deta hai?','Source ki jagah ke andaaze se jawaab; app ki permission aur data ki jagah phir bhi chahiye',['Saboot ki har request ke waqt har user sach mein chune hue region mein hai','DNS record se encryption aur database replication ki policy apne aap laagu hoti hai','Guarantee ki VPN users aur saare recursive resolvers client ki asli jagah batate hain'],1,'Geolocation DNS source/ECS ki andaazan jagah map karti hai; residency ke liye aur controls chahiye. Asli jagah alag ho sakti hai, aur DNS encryption/replication laagu nahi karta, na VPN ko rokta hai.','secure'),
      Q('Primary aur secondary dono ke health checks fail hain. Failover ka kaunsa behaviour plan karna hai?','Fail-open mein primary ka jawaab aa sakta hai; healthy backup aur app recovery phir bhi chahiye',['DNS hamesha poori hosted zone hata deta hai aur domain registration cancel kar deta hai','Har query apne aap tab tak rukti hai jab tak asli DB restore poora na ho jaaye','Route53 apne aap record set ke bahar ka koi teesre region ka endpoint chun leta hai'],2,'Dono unhealthy hon toh failover primary de sakta hai. DNS registration delete nahi karta, DB restore ka wait nahi karta, na bina set kiye teesra endpoint banata hai; failure runbooks test karo.','resilient'),
      Q('Ek public zone, 1 crore standard queries/mahina, ek non-AWS basic HTTP check. Kul kharcha?','Lagbhag $5.25/mahina, optional features, targets, registration aur tax se pehle',['Lagbhag $4.00/mahina, jisme unlimited zones, saare health checks aur servers bhi hain','Lagbhag $0.75/mahina, kyunki AWS ke bahar har aam A query free hai','Lagbhag $7.25/mahina, kyunki default 30 second checks ko fast 10 second add-on chahiye'],3,'Lagbhag $0.50 zone + $4 queries + $0.75 check = $5.25. $4 mein fixed hisse chhoot gaye. Aam A queries free nahi. $2 ka fast add-on is non-AWS example mein sirf tab lagta hai jab chuna ho.','cost-optimized'),
      {terminal:(function(){const a=seed();a.hostedZones[0].records=[...a.hostedZones[0].records.slice(0,2),apex(),...weighted(),...failover().map(r=>{const x={...r,TTL:3600};delete x.HealthCheckId;return x;})];a.healthChecks=[{id:HC,callerReference:'shop-primary-v1',config:{...config(),Inverted:false,Disabled:false},observedHealthy:false,version:1}];const tasks=[{text:'Pehle se bana primary check juda; chalu pair TTL 60; fixture jawaab maintenance',check:s=>healthOK(s)&&contains(served(s),failover())&&!!zone(s)&&eq(AG.dnsAnswer(s.account,zone(s),'status.shopkaro.in','A'),['203.0.113.20'])},{text:'Apex/weighted/zone bache rahe; sirf planned records aur INSYNC edits',check:s=>preserved(s)&&contains(served(s),[apex(),...weighted()])&&served(s).length===7&&(s.account.dnsChanges||[]).length>0&&(s.account.dnsChanges||[]).every(c=>c.Status==='INSYNC')}];const solution=['aws route53 change-resource-record-sets --hosted-zone-id ZSHOP --change-batch file://repair-failover.json','aws route53 wait resource-record-sets-changed --id /change/C000000001'];return {title:'🖥️ Pehle se bana health check use nahi ho raha: theek karo, naya mat banao',goal:'Pehle se bana primary /ready HTTP check (ID 00000000-0000-4000-8000-000000000001) unhealthy hai. Abhi status primary par HealthCheckId nahi hai aur pair ka TTL 3600 hai. cat repair-failover.json dekho; pehle wale record pair ko update karo + authoritative waiter chalao. Purana apex/canary/assets bachao.',account:a,files:{'repair-failover.json':file(batch(failover()))},tasks,success:AG.allOf(tasks),solution,hints:solution.slice(),successText:'Chalu failover pair pehle wala check aur TTL 60 use karta hai; pakka jawaab maintenance ka documentation IP hai. Clients ke purane caches abhi bhi runtime par check karne hain.'};})()},
    ]},
    success:['DNS delegation, pakka jawaab aur client ka cache alag-alag samjha sakta hoon','Alias/CNAME/apex ke niyam aur 8 policies ke signal chun sakta hoon','JSON se state theek kar sakta hoon, aur health association/propagation check kar sakta hoon','DNS failover ko app/data recovery aur emulator ke data se alag pehchaan sakta hoon'],
    homework:'<p><b>Optional, sirf approved asli AWS sandbox mein (paisa lagega):</b> domain/zone/query/health/ALB/CDN ka kharcha nikaalo. Ek delegated test subdomain use karo; production domain ko overwrite mat karo. Supported ALB Alias target ki details padho, readiness check aur active-passive endpoints review karo. Test se pehle TTL kam karo, purane TTL ka time poora hone do, phir approved endpoint failure daal kar naye pakke jawaab, kai recursive resolvers aur asli app recovery alag-alag naapo. Data loss/replication lag aur retry ka behaviour likho. Cleanup: exact test records delete karo, change propagate hone ka wait karo, health checks hatao, sirf test wali hosted zone delete karo, lab ke ALB/listeners/target groups aur baaki target resources saaf karo. Domain ka auto-renew aur registration ka kharcha alag dekho. Shared zone ke NS/SOA ya purane records reset mat karo.</p>',
    cards:[{front:'TTL kya control karta hai?',back:'DNS jawaab cache mein kitne second rahe, yeh batata hai. TTL kam karne se pehle cache hue purane jawaab saaf nahi hote; apps/connections aur der jod sakte hain.'},{front:'Apex ALB: Alias vs CNAME?',back:'Supported Alias A/AAAA, target ke DNSName + HostedZoneId ke saath. CNAME zone apex par nahi ho sakta; aam A Value mein IPv4 chahiye.'},{front:'Weighted 90/10 kis cheez ki ginti par hai?',back:'Pakke DNS jawaabon ka relative hissa. Shared caches, traffic aur connections ki wajah se users/HTTP ka bilkul split nahi; saare weights 0 → barabar chance.'},{front:'Latency vs geoproximity?',back:'Latency: AWS ki naapi hui regional network performance. Geoproximity: user/resource ki doori + bias; TrafficFlow ke bina seedhi policy milti hai.'},{front:'Endpoint check ki default settings?',back:'Har checker 30 second; lagatar 3 checks ka threshold. Fast 10 second optional extra charge hai; kai checkers ka jod hai, isliye koi exact global limit nahi.'},{front:'Aam primary par HealthCheckId nahi?',back:'Aam taur par healthy maana jaata hai. Sahi readiness check jodo; Alias EvaluateTargetHealth supported target ki health alag se le sakta hai.'},{front:'INSYNC proves what?',back:'Route53 ka pakka change phail gaya. Isse recursive cache saaf nahi hota, client ke connection shift nahi hote, DB copy nahi hota, na app wapas chalti hai.'},{front:'On-premises se private zone?',back:'Resolver inbound endpoint, office mein forwarding aur allowed routing/security. Sabse specific private zone mein record na ho toh NXDOMAIN aa sakta hai; public par apne aap wapas nahi jaata.'}],
  }]);
})();
